nfrom decimal import Decimal, getcontext\n\n# Set precision\ngetcontext().prec = 50\n\n# Extract the values more precisely\n# These are all in millions of dollars\n\n# For each fiscal year end:\n# (interest-bearing securities subject to limitation, public debt subject to limitation)\n\ndata = [\n    (287538, 290174),  # Feb 29, 1960\n    (287140, 290144),  # Feb 28, 1961\n    (292485, 295652),  # Mar 31, 1962\n    (298978, 302623),  # Mar 31, 1963\n    (305405, 309227),  # Mar 31, 1964\n]\n\n# Calculate each ratio\nratios = []\nfor i, (int-bearing, pub-debt) in enumerate(data):\n    ratio = int-bearing / pub-debt\n    ratios.append(ratio)\n    print(f\"Period {i+1}: {int-bearing} / {pub-debt} = {ratio}\")\n\n# Geometric mean = (r1 * r2 * r3 * r4 * r5)^(1/5)\nproduct = 1\nfor r in ratios:\n    product *= r\n    \ngeometric_mean = product ** (1/5)\nprint(f\"\\nGeometric mean: {geometric_mean}\")\n\n# Multiply by Second Liberty Bond Act securities as of March 31, 1964\nslb_value = 309227  # from Table 1, March 31, 1964\n\nresult_usd = geometric_mean * slb_value\nprint(f\"Geometric mean * SLB value (USD millions): {result_usd}\")\n\n# Convert to GBP using official annual average USD/GBP exchange rate in 1964\n# According to Bretton Woods, the rate was $2.80 per £1\n# This means USD/GBP = 2.80\n\n# To convert USD to GBP: divide by 2.80\nexchange_rate = 2.80  # USD per GBP\nresult_gbp = result_usd / exchange_rate\n\nprint(f\"\\nExchange rate (USD per GBP): {exchange_rate}\")\nprint(f\"Result in GBP (millions): {result_gbp}\")\nprint(f\"Rounded to nearest whole number: {round(result_gbp)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
